using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Security.Cryptography; using System.Text; using HMS.Application.Authentication.Abstractions; using Microsoft.Extensions.Configuration; using Microsoft.IdentityModel.Tokens;
namespace HMS.Infrastructure.Authentication;
internal sealed class Pbkdf2PasswordHasher : IPasswordHasher { public (string Hash,string Salt) Hash(string p){var s=RandomNumberGenerator.GetBytes(16);var h=Rfc2898DeriveBytes.Pbkdf2(p,s,310000,HashAlgorithmName.SHA512,64);return(Convert.ToBase64String(h),Convert.ToBase64String(s));} public bool Verify(string p,string h,string s)=>CryptographicOperations.FixedTimeEquals(Convert.FromBase64String(h),Rfc2898DeriveBytes.Pbkdf2(p,Convert.FromBase64String(s),310000,HashAlgorithmName.SHA512,64)); }
internal sealed class JwtTokenService : ITokenService { private readonly string _issuer,_audience,_key; public JwtTokenService(IConfiguration c){_issuer=c["Jwt:Issuer"]??throw new InvalidOperationException("Jwt:Issuer is required.");_audience=c["Jwt:Audience"]??throw new InvalidOperationException("Jwt:Audience is required.");_key=c["Jwt:SigningKey"]??throw new InvalidOperationException("Jwt:SigningKey is required.");} public IssuedToken CreateAccessToken(Guid id,string username,IReadOnlyCollection<string> roles,IReadOnlyCollection<string> permissions){var j=Guid.NewGuid();var claims=new List<Claim>{new(JwtRegisteredClaimNames.Sub,id.ToString()),new(JwtRegisteredClaimNames.UniqueName,username),new(JwtRegisteredClaimNames.Jti,j.ToString())};claims.AddRange(roles.Select(x=>new Claim(ClaimTypes.Role,x)));claims.AddRange(permissions.Select(x=>new Claim("permission",x)));var expiry=DateTimeOffset.UtcNow.AddMinutes(15);var token=new JwtSecurityToken(_issuer,_audience,claims,expires:expiry.UtcDateTime,signingCredentials:new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_key)),SecurityAlgorithms.HmacSha512));return new(new JwtSecurityTokenHandler().WriteToken(token),j,expiry);} public string CreateRefreshToken()=>Convert.ToBase64String(RandomNumberGenerator.GetBytes(64));public byte[] HashToken(string t)=>SHA256.HashData(Encoding.UTF8.GetBytes(t)); }
